import {TITLES,PLACES,RUNES,SYMBOLS,STONES,TARGET,rotate,rootStatus,runeClues,runesSolved,totals,balanceSolved,freshState,restoreState} from './puzzle-model.mjs?v=water19';
const $=id=>document.getElementById(id),dialog=$('quest-dialog'),body=$('quest-body'),KEY='elyndra-heartbeats-v1';let state,storage=true;try{state=restoreState(localStorage.getItem(KEY))}catch{state=freshState();storage=false}
let current=-1,priorFocus=null,replay=false,memoryMode='ready',memoryInput=[],timers=[],generation=0;
const HINTS=[['Begin bij de bron linksboven. Een verbinding werkt alleen als twee openingen op elkaar aansluiten.','Alle zestien tegels moeten meedoen. Aan de rechterkant van rij 2 zit een afvoer; de andere zit links aan rij 4.','Het hoofdpad slingert: rij 1 naar rechts, rij 2 terug naar links, rij 3 naar rechts en rij 4 naar links. De T-splitsing voedt de zijtak.'],['Vul eerst de vaste plaats in. De Ster hoort op plek 4, geteld vanaf links.','Zaad en Wortel vormen een paar. Water en Blad vormen ook een paar. Maan moet vóór het eerste paar passen.','Van links naar rechts: Maan, Zaad, Wortel, Ster, Water, Blad.'],['Je hebt precies drie stenen nodig. Elke steen beïnvloedt alle drie de tuinen tegelijk.','Vergelijk de doelwaarden 7, 5, 5. Zoek eerst een combinatie die bij Wind op 7 uitkomt.','Activeer stenen A, C en D. Samen leveren ze 7 Wind, 5 Water en 5 Groei.'],['Je kunt de lichtreeks onbeperkt opnieuw bekijken. Er is geen haast bij het invoeren.','Elke nieuwe reeks bouwt voort op de vorige. Verdeel de langste reeks in een groepje van vier en een groepje van drie.','Het volledige spoor is: Mos → Ster → Wortel → Water → Mos → Wortel → Ster.']];
const memoryNames=['Wortel','Mos','Water','Ster'];
function pause(){window.elyndraVisionOpen=true;dispatchEvent(new Event('elyndra-vision-open'))}
function update(){window.elyndraGame={unlocked:i=>!!state.solved[i],count:()=>state.solved.filter(Boolean).length};$('vision-count').textContent=state.solved.filter(Boolean).length+'/4';if(!storage)$('quest-storage').textContent='Opslaan is hier niet beschikbaar; voortgang blijft alleen tijdens deze sessie bewaard.';dispatchEvent(new CustomEvent('elyndra-game-update',{detail:{solved:[...state.solved]}}))}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{storage=false}update()}
function stopMemory(){generation++;for(let t of timers)clearTimeout(t);timers=[];memoryMode='ready';memoryInput=[]}
function message(t){$('quest-message').textContent=t}
function open(i=-1){if(!Number.isInteger(i)||i<-1||i>3)i=-1;stopMemory();priorFocus=document.activeElement;current=i;replay=false;const vision=$('vision-dialog');if(vision.open)vision.close();pause();if(!dialog.open)dialog.showModal();render();$('quest-close').focus()}
window.elyndraStartPuzzle=open;
function render(){message('');$('quest-hint-text').textContent=current>=0&&state.hints[current]?HINTS[current][state.hints[current]-1]:'';const solved=current>=0&&state.solved[current]&&!replay;$('quest-title').textContent=current<0?'Herstel het levende woud':TITLES[current];$('quest-overview').hidden=current<0;$('quest-hint').hidden=current<0||solved;$('quest-reset').hidden=current<0||solved;$('quest-hint').textContent=current>=0?`Een hint · ${state.hints[current]}/3`:'Een hint';if(current<0)return overview();if(solved)return wonScreen();[roots,runes,balance,memory][current]()}
function overview(){const count=state.solved.filter(Boolean).length;body.innerHTML=`<p class="quest-intro">${count===4?'Alle vier de hartslagen klinken weer. Jij bent nu Bewaker van Elyndra. Je visioenen blijven vrij te bekijken.':'Vier oude systemen zijn stilgevallen. Herstel ze met inzicht, aandacht en een beetje geduld. Elke puzzel onthult een fotorealistisch visioen van deze wereld.'}</p><div class="quest-progress" aria-label="${count} van 4 puzzels opgelost">${state.solved.map(v=>`<span class="${v?'done':''}">${v?'✦':'◇'}</span>`).join('')}</div><div class="quest-cards">${TITLES.map((t,i)=>`<button data-quest="${i}" class="quest-card ${state.solved[i]?'solved':''}"><span class="quest-card-number">0${i+1}</span><span><strong>${t}</strong><small>${['Verbindingen · ruimtelijk inzicht','Runen · logisch redeneren','Energie · combineren','Lichtreeks · aandacht & geheugen'][i]}</small><em>${state.solved[i]?'✦ Visioen vrijgespeeld':'◇ Visioen verzegeld'} · ${PLACES[i]}</em></span></button>`).join('')}</div>`;for(let b of body.querySelectorAll('[data-quest]'))b.onclick=()=>{current=Number(b.dataset.quest);replay=false;render()}}
function complete(){const first=!state.solved[current];state.solved[current]=true;replay=false;stopMemory();save();if(first)dispatchEvent(new CustomEvent('elyndra-puzzle-solved',{detail:current}));render();$('quest-reward').focus()}
function wonScreen(){const count=state.solved.filter(Boolean).length;body.innerHTML=`<div class="quest-victory"><span class="quest-seal">✦</span><p class="quest-eyebrow">HARTSLAG ${current+1} HERSTELD · ${count} / 4</p><h3>${['Het woud ademt weer.','De poort herkent je.','De tuinen vinden hun evenwicht.','De moswachter herinnert zich.'][current]}</h3><p>${count===4?'Alle vier de systemen leven weer. Bewaker van Elyndra, dit visioen is van jou.':'Achter het zichtbare wacht een ander Elyndra. Je hebt het bijbehorende visioen vrijgespeeld.'}</p><button id="quest-reward" class="primary">Onthul ${PLACES[current].toLowerCase()} ↗</button><button id="quest-replay">Puzzel opnieuw spelen</button></div>`;$('quest-reward').onclick=()=>{const i=current;dialog.close();dispatchEvent(new CustomEvent('elyndra-reward',{detail:i}))};$('quest-replay').onclick=()=>reset()}
function rootSVG(mask){let path='',ends=[[32,0],[64,32],[32,64],[0,32]];for(let j=0;j<4;j++)if(mask&(1<<j))path+=`M32 32 L${ends[j][0]} ${ends[j][1]} `;return `<svg viewBox="0 0 64 64" aria-hidden="true"><path d="${path}" class="root-channel"/><path d="${path}" class="root-light"/><circle cx="32" cy="32" r="5" fill="currentColor"/></svg>`}
function roots(){const status=rootStatus(state.pipes);body.innerHTML=`<p class="quest-intro">Draai de wortelknooppunten. Verbind de bron met <b>beide afvoeren</b>, voed alle 16 tegels en laat nergens licht weglekken.</p><div class="root-label">BRON ↘ linksboven · AFVOER rechts rij 2 & links rij 4</div><div class="root-grid" role="group" aria-label="Wortelnetwerk met zestien draaibare tegels">${state.pipes.map((m,i)=>`<button data-tile="${i}" class="root-tile ${status.powered.has(i)?'powered':''}" aria-label="Rij ${Math.floor(i/4)+1}, kolom ${i%4+1}; open naar ${['boven','rechts','onder','links'].filter((_,j)=>m&(1<<j)).join(', ')}. Draai een kwartslag.">${rootSVG(m)}<span>${i+1}</span>${i===0?'<b class="root-port source">→</b>':i===7?'<b class="root-port right">→</b>':i===12?'<b class="root-port left">←</b>':''}</button>`).join('')}</div><div class="puzzle-readout"><span>${status.powered.size}/16 gevoed</span><span>${status.leaks} lichtlek${status.leaks===1?'':'ken'}</span></div><p class="puzzle-instruction">Tik op een tegel om hem 90° naar rechts te draaien. Alleen tegels die licht van de bron krijgen tellen mee.</p>`;for(let b of body.querySelectorAll('[data-tile]'))b.onclick=()=>{let i=Number(b.dataset.tile);state.pipes[i]=rotate(state.pipes[i]);save();if(rootStatus(state.pipes).solved)return complete();roots();body.querySelector(`[data-tile="${i}"]`).focus()}}
function runes(){const clues=['De Ster staat op de vierde plaats.','Het Zaad staat direct links van de Wortel.','Het Water staat ergens rechts van de Wortel.','De Maan staat ergens links van het Zaad.','Het Blad staat direct rechts van het Water.'];body.innerHTML=`<p class="quest-intro">De poort opent voor de juiste volgorde. Gebruik elke rune één keer en voldoe aan alle vijf inscripties.</p><ol class="rune-clues">${clues.map(c=>`<li>${c}</li>`).join('')}</ol><div class="rune-slots" aria-label="Zes plaatsen van links naar rechts">${state.runes.map((r,i)=>`<button data-slot="${i}" aria-label="Plaats ${i+1}: ${r===null?'leeg':RUNES[r]+', klik om terug te leggen'}"><small>${i+1}</small><b>${r===null?'·':SYMBOLS[r]}</b><span>${r===null?'Leeg':RUNES[r]}</span></button>`).join('')}</div><div class="rune-bank" aria-label="Beschikbare runen">${RUNES.map((r,i)=>`<button data-rune="${i}" ${state.runes.includes(i)?'disabled':''}>${SYMBOLS[i]} ${r}</button>`).join('')}</div><p class="puzzle-instruction">Kies een rune voor de eerste lege plek. Tik op een geplaatste rune om hem terug te leggen.</p><button id="rune-check" class="primary">Lees de inscriptie</button>`;for(let b of body.querySelectorAll('[data-rune]'))b.onclick=()=>{let empty=state.runes.indexOf(null);if(empty<0)return;state.runes[empty]=Number(b.dataset.rune);save();runes()};for(let b of body.querySelectorAll('[data-slot]'))b.onclick=()=>{state.runes[Number(b.dataset.slot)]=null;save();runes();};$('rune-check').onclick=()=>{if(state.runes.includes(null))return message('Leg eerst alle zes runen neer.');if(runesSolved(state.runes))return complete();message(`${runeClues(state.runes).filter(Boolean).length} van de 5 inscripties kloppen. Kijk vooral naar het verschil tussen ‘direct’ en ‘ergens’.`)}}
function balance(){const sum=totals(state.stones),count=state.stones.filter(Boolean).length;body.innerHTML=`<p class="quest-intro">Activeer <b>precies drie magneetstenen</b>. Samen moeten ze de drie tuinen exact de juiste energie geven.</p><div class="balance-gauges">${['Wind','Water','Groei'].map((name,j)=>`<div class="balance-gauge ${sum[j]===TARGET[j]?'matched':sum[j]>TARGET[j]?'over':''}"><span>${name}</span><strong>${sum[j]} <small>/ ${TARGET[j]}</small></strong><progress value="${Math.min(sum[j],TARGET[j])}" max="${TARGET[j]}" aria-label="${name}: ${sum[j]} van ${TARGET[j]}"></progress><small>${sum[j]===TARGET[j]?'In balans':sum[j]>TARGET[j]?`${sum[j]-TARGET[j]} te veel`:`${TARGET[j]-sum[j]} tekort`}</small></div>`).join('')}</div><div class="stone-grid">${STONES.map((s,i)=>`<button data-stone="${i}" aria-pressed="${state.stones[i]}" class="${state.stones[i]?'selected':''}"><strong>Steen ${String.fromCharCode(65+i)}</strong><span>Wind ${s[0]} · Water ${s[1]} · Groei ${s[2]}</span><small>${state.stones[i]?'Actief':'Activeren'}</small></button>`).join('')}</div><p class="puzzle-instruction">${count}/3 stenen actief. Elke steen telt in alle drie de tuinen mee. Tik nogmaals om een steen uit te zetten.</p><button id="balance-check" class="primary">Stabiliseer de tuinen</button>`;for(let b of body.querySelectorAll('[data-stone]'))b.onclick=()=>{let i=Number(b.dataset.stone);state.stones[i]=!state.stones[i];save();balance();body.querySelector(`[data-stone="${i}"]`).focus()};$('balance-check').onclick=()=>{if(count!==3)return message('Er moeten precies drie stenen actief zijn.');if(balanceSolved(state.stones))return complete();message('Nog niet stabiel. Eén combinatie brengt alle drie de tuinen tegelijk in balans.')};}
function memory(){const length=[3,5,7][state.round];body.innerHTML=`<p class="quest-intro">De moswachter is zijn oude lichttaal vergeten. Bekijk de reeks en geef de lichtsignalen in dezelfde volgorde terug.</p><div class="memory-rounds">${[3,5,7].map((n,i)=>`<span class="${i<state.round?'done':i===state.round?'current':''}">${i<state.round?'✓':i+1} · ${n} signalen</span>`).join('')}</div><div class="memory-grid">${memoryNames.map((n,i)=>`<button data-memory="${i}" aria-label="Licht ${i+1}: ${n}" disabled><b>${['⌘','❧','≈','✦'][i]}</b><span>${i+1} · ${n}</span></button>`).join('')}</div><p id="memory-status" role="status">Ronde ${state.round+1}: ${length} signalen. Bekijk de reeks als je klaar bent.</p><div class="memory-actions"><button id="memory-watch" class="primary">Bekijk de lichtreeks</button><button id="memory-clear" disabled>Mijn invoer wissen</button></div><p class="puzzle-instruction">Geen tijdsdruk. Je mag zo vaak kijken als je wilt. Een fout kost alleen je huidige poging.</p>`;for(let b of body.querySelectorAll('[data-memory]'))b.onclick=()=>inputMemory(Number(b.dataset.memory));$('memory-watch').onclick=playMemory;$('memory-clear').onclick=()=>{memoryInput=[];$('memory-status').textContent='Invoer gewist. Begin opnieuw met het eerste signaal.';};}
function playMemory(){stopMemory();const token=generation,sequence=state.sequence.slice(0,[3,5,7][state.round]);memoryMode='show';$('memory-watch').disabled=true;$('memory-clear').disabled=true;for(let b of body.querySelectorAll('[data-memory]'))b.disabled=true;let delay=450;sequence.forEach((value,index)=>{timers.push(setTimeout(()=>{if(token!==generation)return;const b=body.querySelector(`[data-memory="${value}"]`);b.classList.add('lit');$('memory-status').textContent=`Signaal ${index+1}: ${value+1} · ${memoryNames[value]}`;},delay));timers.push(setTimeout(()=>{if(token===generation)body.querySelector(`[data-memory="${value}"]`).classList.remove('lit')},delay+650));delay+=1000});timers.push(setTimeout(()=>{if(token!==generation)return;memoryMode='input';memoryInput=[];for(let b of body.querySelectorAll('[data-memory]'))b.disabled=false;$('memory-watch').disabled=false;$('memory-watch').textContent='Bekijk de reeks opnieuw';$('memory-clear').disabled=false;$('memory-status').textContent=`Jouw beurt: geef ${sequence.length} signalen terug.`;},delay));}
function inputMemory(value){if(memoryMode!=='input')return;const length=[3,5,7][state.round];if(value!==state.sequence[memoryInput.length]){memoryInput=[];$('memory-status').textContent='Bijna. Deze poging begint opnieuw bij het eerste signaal. Je mag de reeks nogmaals bekijken.';return}memoryInput.push(value);$('memory-status').textContent=`${memoryInput.length}/${length} signalen teruggegeven.`;if(memoryInput.length===length){if(state.round===2)return complete();state.round++;save();stopMemory();memory();message('De moswachter herkent dit fragment. De volgende reeks is iets langer.')}}
function reset(){stopMemory();replay=true;const fresh=freshState();if(current===0)state.pipes=fresh.pipes;if(current===1)state.runes=fresh.runes;if(current===2)state.stones=fresh.stones;if(current===3)state.round=0;save();render()}
$('quest-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{stopMemory();window.elyndraVisionOpen=!!document.querySelector('dialog[open]');if(!window.elyndraVisionOpen)priorFocus?.focus()});$('quest-overview').onclick=()=>{stopMemory();current=-1;replay=false;render()};$('quest-hint').onclick=()=>{if(current<0)return;state.hints[current]=Math.min(3,state.hints[current]+1);save();$('quest-hint-text').textContent=HINTS[current][state.hints[current]-1];$('quest-hint').textContent=`Een hint · ${state.hints[current]}/3`};$('quest-reset').onclick=reset;
addEventListener('keydown',e=>{if(dialog.open&&e.code==='KeyV')e.preventDefault()});update();
